public class Solution {
    public static void main(String[] args) {
        // Warm-up phase to trigger JIT compilation
        for (int i = 0; i < 20_000; i++) {
            compute(i);
        }

        long start = System.nanoTime();
        long result = compute(100_000);
        long elapsed = System.nanoTime() - start;

        System.out.println("JIT warm-up completed.");
        System.out.println("Optimized method executed: result = " + result);
    }

    private static long compute(int n) {
        long total = 0;
        for (int i = 0; i < 1_000; i++) {
            total += (n ^ i);
        }
        return total;
    }
}

